def load_queue(jobs, arrivals):
    jobs.append("calibrate")
    jobs.extend(arrivals)
    jobs.insert(0, "power_on")


def clear_one(jobs, unwanted):
    jobs.remove(unwanted)
    return jobs.pop()


def ranked(sites):
    return sorted(sites)


def rank_here(sites):
    return sites.sort()

