question.answer:
def tidy(readings, drop):
    work = readings[:]
    while drop in work:
        work.remove(drop)
    work.extend([0, 100])
    return sorted(work)


def rotate(readings):
    work = readings[:]
    work.insert(0, work.pop())
    return work


def sort_result(readings):
    return readings[:].sort()

