question.answer:
import copy


def shared_grid():
    row = [0, 0, 0]
    return [row, row, row]


def independent_grid():
    return [[0, 0, 0], [0, 0, 0], [0, 0, 0]]


def wipe(batches):
    for batch in batches:
        batch.clear()


def replace(batches):
    batches = [[9, 9]]
    return batches


def shallow_and_deep(records):
    return records[:], copy.deepcopy(records)
